"""Render retained research evidence. Never trains, samples, or modifies checkpoints."""
import html
import json
import re
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
def read(name):return json.loads((ROOT/'docs'/name).read_text())
def esc(value):return re.sub(r' +(?=\n|$)',lambda m:'&#32;'*len(m.group()),html.escape(str(value)))
def fmt(value,digits=3):return f'{value:,.{digits}f}'
def table(headers,rows):
    return '<div class="table-wrap"><table><thead><tr>'+''.join(f'<th>{esc(v)}</th>' for v in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{esc(v)}</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'

def curve(series,title):
    """Static scientific plot: unsmoothed recorded points, shared axes, readable labels."""
    width,height=940,330
    values=[m['val'] for _,metrics,_ in series for m in metrics]
    lo=max(0,min(values)-.15);hi=max(values)*1.03
    last=max(m['step'] for _,metrics,_ in series for m in metrics)
    x=lambda s:55+s/max(1,last)*860
    y=lambda v:285-(v-lo)/(hi-lo)*245
    parts=[f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="{esc(title)}"><title>{esc(title)}</title>']
    for i in range(5):
        v=lo+(hi-lo)*i/4;yy=y(v)
        parts.append(f'<path d="M55 {yy:.1f}H915" stroke="#202633"/><text x="40" y="{yy+4:.1f}" text-anchor="end">{v:.1f}</text>')
        s=last*i/4
        parts.append(f'<text x="{x(s):.1f}" y="312" text-anchor="middle">{s:,.0f}</text>')
    for name,metrics,color in series:
        points=' '.join(f'{x(m["step"]):.1f},{y(m["val"]):.1f}' for m in metrics)
        parts.append(f'<polyline points="{points}" fill="none" stroke="{color}" stroke-width="2.5"/>')
    parts.append('</svg><div class="legend">'+''.join(f'<span style="--key:{color}">{esc(name)}</span>' for name,_,color in series)+'</div>')
    return ''.join(parts)

def sample_groups(groups):
    out=[]
    for name,samples in groups:
        out.append(f'<details><summary>{esc(name)} / {len(samples)} retained samples</summary>')
        for sample in samples:
            out.append(f'<article class="sample"><p class="prompt">{esc(sample["prompt"])}</p><small>Seed {sample["seed"]} · {sample["tokens"]} generated tokens</small><pre>{esc(sample["text"])}</pre></article>')
        out.append('</details>')
    return ''.join(out)

coherence=read('coherence-results.json');conditions=coherence['conditions'];runs={r['kind']:r for r in coherence['runs']}
stories=read('stories-results.json');chat=read('chat-research-results.json');review=read('quality-review.json')
continuation=read('stories-continuation-results.json')
legacy=read('legacy-evidence.json');old=read('training-comparison.json')
arch_rows=[];timing_rows=[]
for seed in [42,123]:
    base=runs[f'classic_{seed}'];new=runs[f'revised_{seed}']
    for kind,run in [('classic',base),('revised',new)]:
        score=conditions[f'{kind}_{seed}']['scores']['scratch_test']['bits_per_byte'];s=run['summary']
        arch_rows.append([seed,kind.title(),fmt(s['parameters']/1e6),fmt(score),fmt(s['steady_ms_per_step'],1)+' ms',fmt(s['elapsed'],1)+' s'])
    hit=next(m for m in new['metrics'] if m['val']<=base['summary']['best_loss'])
    timing_rows.append([seed,fmt(base['summary']['best_loss']),f'{hit["step"]:,}',fmt(hit['elapsed'],1)+' s',fmt(base['summary']['elapsed'],1)+' s'])
continued_rows=[]
for key,label in [('original','Original weights'),('continued_ce','Continued / standard'),('continued_ul','Continued / unlikelihood')]:
    c=conditions[key];s=c['summary']
    continued_rows.append([label,fmt(c['scores']['historical_test']['bits_per_byte']),fmt(c['scores']['external_hamlet']['bits_per_byte']),fmt(s['mean_repeated_word_4grams']*100,2)+'%',s['paragraph_markers']])
chat_rows=[[name,fmt(r['historical_test']['bits_per_byte']),r['checkpoint_step']] for name,r in chat['results'].items()]
ss=stories['runs'][0]['summary']
legacy_rows=[[m['name'],fmt(m['metadata']['params']/1e6,1)+'M',fmt(m['metadata']['training_metadata']['best_val_loss'])] for m in legacy['models']]
sections=[]
sections.append('<section><h2>Your foundation</h2><p>You already built a custom decoder, data preparation, GPU training, checkpointing, generation and a desktop launcher. This work extends that code and keeps your original trained weights intact.</p>'+table(['Original family','Historical parameter count','Historical validation'],legacy_rows)+'<p class="fine">Historical metadata excludes positional embeddings in its parameter count. Different training sets mean these validation values are not a ranking across models.</p></section>')
sections.append('<section><span class="eyebrow">01 / Learned weights</span><h2>Continuing your Shakespeare model</h2><p>Both candidates started from your actual best 30.04M-parameter checkpoint. Cleaning artificial paragraph markers and continuing training improved prediction on the reserved text and an external Hamlet excerpt.</p>'+table(['Condition','Historical bits/byte ↓','Hamlet bits/byte ↓','Word repetition','Paragraph markers'],continued_rows)+'<p>'+esc(review['shakespeare'])+'</p><p class="fine">1,200 updates each; original vocabulary and architecture retained. Historical test: 50,597 bytes; Hamlet: 30,000 bytes. The parent was selected using the whole historical validation tail, so that tail is not selection-naive. Hamlet was not used for training or selection. Twelve samples per condition: six fixed prompts × two seeds, up to 160 tokens, temperature 0.8, top-k 50, top-p 0.9, no repetition penalties. Repetition is the mean duplicate word 4-gram fraction; markers are counted across all outputs.</p></section>')
sections.append('<section><span class="eyebrow">02 / Transformer experiment</span><h2>More learning within the same step budget</h2><p>The revised block combines RMSNorm, rotary positions and a SwiGLU feed-forward layer. Both models use approximately 2.6M parameters, the same data, compact vocabulary, context and 1,500-update budget. The revised block scored better in both seeds.</p>'+curve([('Classic / seed 42',runs['classic_42']['metrics'],'#91b8f3'),('Revised / seed 42',runs['revised_42']['metrics'],'#bea6e7')],'Validation loss versus training steps; architecture comparison, seed 42')+table(['Seed','Block','Parameters / M','Test bits/byte ↓','Steady step','Run elapsed'],arch_rows)+'<h3>Time to reach the classic run’s final validation level</h3>'+table(['Seed','Target loss','Revised step','Revised elapsed','Classic full run'],timing_rows)+'<p>'+esc(review['architecture'])+'</p><p class="fine">Full held-out test: 111,537 bytes, identical in all four conditions. Revised steps are about 10% slower; learning efficiency is the improvement here. Threshold-crossing times are derived after the experiment, at discrete evaluation points; they are not an equal-time retraining trial. Timings include worker evaluation/saves but exclude preflight, data/model initialization and tokenizer fitting. Current classic initialization order differs from the preceding release, so these runs are compared only with their paired current implementation. Two seeds, one small corpus, one architecture bundle—not proof that every component helps independently or that all model sizes benefit.</p></section>')
sections.append('<section><span class="eyebrow">03 / Clean-language study</span><h2>Teach a small model a clearer task</h2><p>Public TinyStories training text, your Transformer code, fresh random weights. The data is restricted to simple stories: 20,000 whole stories for training, 500 for validation and 500 held out. Exact duplicate stories were removed before partitioning.</p>'+curve([('Training',[{**m,'val':m['train']} for m in stories['runs'][0]['metrics']],'#91b8f3'),('Validation',stories['runs'][0]['metrics'],'#bea6e7')],'Simple-stories training and validation loss versus training steps')+table(['Parameters','Training updates','Best step','Run elapsed','Test bits/byte ↓'],[[fmt(ss['parameters']/1e6)+'M',ss['step'],ss['best_step'],fmt(ss['elapsed']/60,1)+' min',fmt(stories['test']['bits_per_byte'])]])+'<p>'+esc(review['stories'])+'</p><p class="fine">One Mini model: six layers, width 192, six heads, revised blocks, 4,096-token vocabulary fitted on training text, context 256, batch 16, LR 5e-4. Test covers the first 100,000 characters of the reserved stories; EOS separators count in the denominator. These test scores cannot be compared numerically with Shakespeare scores on different text. This is an exploratory data/task change, not a controlled architecture comparison or a general assistant. No pretrained weights were downloaded.</p></section>')
cs=continuation['runs'][0]['summary']
continuation_rows=[[name,fmt(value['test']['bits_per_byte']),fmt(value['mean_word_repeat_fraction']*100,2)+'%'] for name,value in continuation['conditions'].items()]
sections.append('<section><h2>A second, fixed training budget</h2><p>After reviewing the first story samples, one further 5,000-step continuation tested whether more learning with dropout disabled would help. It keeps the same model, vocabulary, data and context, with a fresh optimizer and LR 3e-4. These combined changes are exploratory.</p>'+curve([('Continued training',[{**m,'val':m['train']} for m in continuation['runs'][0]['metrics']],'#91b8f3'),('Continued validation',continuation['runs'][0]['metrics'],'#bea6e7')],'Continued story model: training and validation loss versus additional steps')+table(['Condition','Same new test slice / bits per byte ↓','Word repetition'],continuation_rows)+'<p>'+esc(review['story_continuation'])+'</p><p class="fine">Additional run: '+fmt(cs['elapsed']/60,1)+' minutes; selected additional step '+str(cs['best_step'])+'. Both models were scored on characters 100,000–199,999 of the reserved story partition, unseen by the first scoring round. This is a fresh slice of the same partition, chosen adaptively after initial outputs, not an independent dataset. The prompts informed the decision to continue; performance on them is exploratory. No further tuning on these outputs was performed.</p></section>')
sections.append('<section><span class="eyebrow">04 / Your existing chat model</span><h2>Keep the original as the control</h2>'+table(['Condition','Historical test bits/byte ↓','Selected checkpoint step'],chat_rows)+'<p>'+esc(review['chat'])+'</p><p class="fine">Same original chat weights and vocabulary, up to 800 updates, LR 3e-5, one seed. Starting weights are saved at step zero; new best weights must improve validation. The parent previously used the historical validation tail for selection. This is aggregate historical evaluation, without a fresh external chat test or independent coherence ratings. Private source text and generated chat are not included in this report.</p></section>')
sections.append('<section><h2>Read the generated text</h2><p>Every planned public sample is retained below, including awkward grammar and failed continuity. These are the full returned continuations, up to their token limit or end-of-text. No semantic judge score is claimed. The original Shakespeare model’s simple-story outputs are a demonstration of task mismatch, not a fair in-domain benchmark.</p>'+sample_groups([('stories_continued',continuation['conditions']['continued']['samples'])])+sample_groups([(name,value['samples']) for name,value in stories['generation'].items()])+sample_groups([(name,value['samples']) for name,value in conditions.items()])+'</section>')
old_rows=[[r['config'].get('tokenizer','gpt2'),r['summary']['step'],fmt(r['summary']['steady_ms_per_step'],2)+' ms',fmt(r['summary']['test']['bits_per_byte'])] for r in old['runs']]
sections.append('<section><details><summary>Earlier negative results and training repairs</summary><p>The earlier compact-vocabulary pilot was faster per step but scored worse at both tested budgets. Its 800-step extension was exploratory. The original vocabulary stays available and remains the vocabulary default; the new architecture is the default for new runs based on the paired study, while continued models inherit their own architecture.</p>'+table(['Vocabulary','Steps','Steady step','Test bits/byte ↓'],old_rows)+'<p>Hard phrase blocking eliminated repeated phrases mechanically but distorted speaker labels. Unlikelihood reduced token repetition in the continued Shakespeare trial, yet word repetition worsened relative to ordinary continuation. Standard likelihood and unpenalized sampling therefore remain the defaults.</p><p>The new worker also saves best weights immediately, restores optimizer/random state on resume, excludes bias/norm vectors from weight decay, and retains raw uploads. Continued training uses a private run-local copy of the source checkpoint. Originals remain read-only.</p></details></section>')
sources=[('TinyStories','https://arxiv.org/html/2305.07759v1'),('LLaMA, section 2.2','https://arxiv.org/html/2302.13971v1'),('SwiGLU','https://arxiv.org/abs/2002.05202'),('RMSNorm','https://arxiv.org/abs/1910.07467'),('RoPE','https://arxiv.org/abs/2104.09864'),('Unlikelihood training','https://arxiv.org/html/1908.04319v2'),('Compute-optimal training','https://arxiv.org/abs/2203.15556'),('TinyStories dataset','https://huggingface.co/datasets/roneneldan/TinyStories'),('Dataset license / CDLA-Sharing-1.0','https://cdla.dev/sharing-1-0/'),('External Hamlet source','https://shakespeare.mit.edu/hamlet/full.html')]
sections.append('<section><h2>Research and reproducibility</h2><p>The architecture papers motivate experiments; their large-model results do not establish gains for VV-GPT. The unlikelihood objective is a bounded 32-token context adaptation, not a full paper reproduction. Protocol, configurations, hashes, measurements and all public samples are retained locally in the project.</p><div class="sources">'+''.join(f'<a href="{url}">{esc(name)} ↗</a>' for name,url in sources)+'</div><p class="fine">TinyStories revision f54c09fd23315a6f9c86f9dc80f725de7d8f9c64; 17,275,507 bytes downloaded. No model weights, paid API or external inference service. Data and checkpoints stay in ignored runtime storage; public research evidence lives in docs.</p></section>')
style='''
:root{color-scheme:dark;font-family:-apple-system,BlinkMacSystemFont,"Avenir Next",sans-serif;background:#080a0f;color:#e4e7ed}*{box-sizing:border-box}body{max-width:1100px;margin:0 auto;padding:58px 40px}header{padding-bottom:38px;border-bottom:1px solid #252936}.eyebrow{color:#959dad;font-size:11px;letter-spacing:.08em}h1{font-size:42px;font-weight:480;letter-spacing:-1.5px;line-height:1.2;margin:19px 0}h2{font-size:25px;font-weight:480;letter-spacing:-.6px;margin:14px 0 20px}h3{font-size:15px;font-weight:500;margin-top:32px}p{font-size:14px;line-height:1.95;color:#a6afbf;max-width:900px}.lead{font-size:16px;max-width:750px}section{padding:36px 0;border-bottom:1px solid #202633}a{color:#91b8f3;text-decoration:none}a:hover{text-decoration:underline}.fine,small{font-size:11px;line-height:1.9;color:#838fa4}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:12px;font-variant-numeric:tabular-nums;margin:25px 0}th,td{text-align:left;padding:14px 12px;border-bottom:1px solid #252936;white-space:nowrap}th{font-weight:450;color:#838fa4}th:first-child,td:first-child{padding-left:0}svg{width:100%;height:auto;display:block;margin-top:25px}svg text{font:11px -apple-system,sans-serif;fill:#838fa4}.legend{display:flex;gap:30px;color:#959dad;font-size:11px;justify-content:center;margin:8px 0 20px}.legend span:before{content:'';display:inline-block;width:20px;height:2px;background:var(--key);vertical-align:middle;margin-right:8px}details{padding:20px 0;border-top:1px solid #252936}summary{font-size:13px;color:#bec7d6;cursor:pointer;line-height:1.8}summary:focus-visible,a:focus-visible{outline:2px solid #91b8f3;outline-offset:5px}.sample{padding:22px 0 12px;border-bottom:1px solid #202633}.prompt{color:#bea6e7;white-space:pre-wrap;font-size:13px}.sample pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.95 -apple-system,sans-serif;max-width:800px}.sources{display:flex;gap:12px 25px;flex-wrap:wrap;font-size:12px;margin-top:25px}footer{font-size:11px;color:#727d90;padding-top:30px;line-height:2}@media(max-width:600px){body{padding:30px 20px}h1{font-size:32px}h2{font-size:22px}section{padding:28px 0}.legend{gap:16px;font-size:10px}p{font-size:13px}}
'''
report='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VV-GPT / Coherence research</title><style>'+style+'</style><header><span class="eyebrow">VV-GPT4 / RESEARCH / 17 NOVEMBER 2026</span><h1>Better learning.<br>Evidence you can inspect.</h1><p class="lead">Changes to your own Transformer, tested against your existing weights. Clearer language is the aim; prediction scores, repetition and coherence are assessed separately.</p><a href="/">Open the local studio ↗</a></header>'+''.join(sections)+'<footer>Source lineage: XavierB100/vv-gpt3 @ 802d1a8<br>Evidence: RESEARCH_PROTOCOL.md · coherence-results.json · stories-results.json · stories-continuation-results.json · chat-research-results.json · quality-review.json<br>Original VV-GPT3 project preserved. Work remains local on enhance-original-models.</footer></html>'
(ROOT/'docs/enhancements.html').write_text(report)
print('Built docs/enhancements.html from retained model research.')
